const LANG_CODES: [&str; 6] = ["en", "ru", "uk", "pt", "es", "zh"];

/// Built-in tables, with `<data>/lang/<code>.json` applied on top when present.
fn tables() -> &'static [&'static Strings; 6] {
    static ACTIVE: OnceLock<[&'static Strings; 6]> = OnceLock::new();
    ACTIVE.get_or_init(|| {
        #[cfg(windows)]
        let base: [&'static Strings; 6] = [&EN, &RU, &UK, &PT, &ES, &ZH];
        // The tables are written for the Windows build; a few entries name things
        // that do not exist here and are replaced before any user override.
        #[cfg(not(windows))]
        let base: [&'static Strings; 6] = {
            let raw: [&'static Strings; 6] = [&EN, &RU, &UK, &PT, &ES, &ZH];
            let mut b = raw;
            for i in 0..6 {
                b[i] = Box::leak(Box::new(raw[i].with_overrides(&linux::text::strings(i))));
            }
            b
        };
        let mut out = base;
        for i in 0..6 {
            let path = paths::lang_dir().join(format!("{}.json", LANG_CODES[i]));
            let Ok(text) = std::fs::read_to_string(&path) else {
                continue;
            };
            match serde_json::from_str::<BTreeMap<String, String>>(&text) {
                Ok(map) => {
                    out[i] = Box::leak(Box::new(base[i].with_overrides(&map)));
                    info!("loaded translation overrides from {}", path.display());
                }
                Err(e) => warn!("bad translation file {}: {e}", path.display()),
            }
        }
        out
    })
}

/// Writes a filled-in template users can translate and drop back into `lang/`.
fn export_lang_template(lang_index: usize) -> Result<PathBuf> {
    let idx = lang_index.min(5);
    let map = tables()[idx].to_map();
    let path = paths::lang_dir().join(format!("{}.template.json", LANG_CODES[idx]));
    std::fs::write(&path, serde_json::to_string_pretty(&map)?)?;
    Ok(path)
}

fn detect_system_lang() -> Lang {
    #[cfg(windows)]
    unsafe {
        let lang = win32::GetUserDefaultUILanguage() as u32;
        match lang & 0x3FF {
            0x19 => Lang::Ru,
            0x22 => Lang::Uk,
            0x16 => Lang::Pt,
            0x0A => Lang::Es,
            0x04 => Lang::Zh,
            _ => Lang::En,
        }
    }
    #[cfg(not(windows))]
    {
        let raw = ["LC_ALL", "LC_MESSAGES", "LANG"]
            .iter()
            .filter_map(|k| std::env::var(k).ok())
            .find(|v| !v.trim().is_empty())
            .unwrap_or_default()
            .to_lowercase();
        match raw.get(..2) {
            Some("ru") => Lang::Ru,
            Some("uk") => Lang::Uk,
            Some("pt") => Lang::Pt,
            Some("es") => Lang::Es,
            Some("zh") => Lang::Zh,
            _ => Lang::En,
        }
    }
}

/// Which language a setting index means, with 0 standing for "whatever Windows is in".
///
/// Pulled out of `get_strings` so the handbook can ask the same question and get the
/// same answer. Two copies of this would eventually disagree, and the symptom would
/// be a window in one language with a manual in another.
fn lang_of(lang_mode: usize, system_lang: Lang) -> Lang {
    match lang_mode {
        1 => Lang::En,
        2 => Lang::Ru,
        3 => Lang::Uk,
        4 => Lang::Pt,
        5 => Lang::Es,
        6 => Lang::Zh,
        _ => system_lang,
    }
}

/// The language the window is showing, as a table index, for threads that have
/// no window to ask.
static UI_LANG_IDX: AtomicUsize = AtomicUsize::new(0);

fn get_strings(lang_mode: usize, system_lang: Lang) -> &'static Strings {
    let lang = lang_of(lang_mode, system_lang);
    let idx = match lang {
        Lang::En => 0,
        Lang::Ru => 1,
        Lang::Uk => 2,
        Lang::Pt => 3,
        Lang::Es => 4,
        Lang::Zh => 5,
    };
    UI_LANG_IDX.store(idx, Ordering::Relaxed);
    tables()[idx]
}

