        let json = r#"{"events":[{"t_us":0,"kind":{"MouseMove":{"x":1,"y":1,"dx":0,"dy":0}}}],
            "script":[{"kind":{"ClickImage":{"template":"claim","threshold":0.85,
            "button":"Left"}},"enabled":true}]}"#;
        let data = parse_macro(json).expect("an older macro must still load");
