        e.action = expander::Action::PlayMacro;
        let b = book_with(vec![e]);
        let f = typed(&b, ";farm").expect("fired");
        assert_eq!(f.action, expander::Action::PlayMacro);
        assert_eq!(f.payload, "C:/macros/farm.mrz");
