    /// Builds a haystack with `tpl` pasted in at (px, py).
    fn haystack(w: u32, h: u32, tpl: &vision::Template, px: u32, py: u32) -> vision::Frame {
        let mut rgba = vec![30u8; (w * h * 4) as usize];
        for i in (3..rgba.len()).step_by(4) {
            rgba[i] = 255;
        }
        for y in 0..tpl.h {
            for x in 0..tpl.w {
                let d = (((py + y) * w + px + x) * 4) as usize;
                let sidx = ((y * tpl.w + x) * 4) as usize;
                rgba[d..d + 4].copy_from_slice(&tpl.rgba[sidx..sidx + 4]);
            }
        }
        vision::Frame::rgba(0, 0, w, h, rgba)
    }

    fn checker_template(w: u32, h: u32) -> vision::Template {
        let mut rgba = vec![0u8; (w * h * 4) as usize];
        for y in 0..h {
            for x in 0..w {
                let i = ((y * w + x) * 4) as usize;
                let v = if (x / 4 + y / 4) % 2 == 0 { 240 } else { 15 };
                rgba[i] = v;
                rgba[i + 1] = v / 2;
                rgba[i + 2] = 255 - v;
                rgba[i + 3] = 255;
            }
        }
        vision::Template { w, h, rgba, name: "checker".into() }
    }

    /// One executable holds a correlation kernel for every instruction set from
    /// baseline x86-64 up to AVX-512 and picks one from CPUID. They have to be the
    /// same function - a kernel that is quick and wrong finds buttons in the wrong
    /// place, and it would only do it on the machines that have it.
    ///
    /// The widths are the point. 32 is a whole number of vectors in all four; 17 and
    /// 63 leave a tail in every one of them; 6 is narrower than a 256-bit vector, so
    /// the wide kernels have to step down to a narrower one rather than spend the
    /// whole window in the tail. Each of those is a separate chance to read past the
    /// end of a row, and the last row of a window ends at the end of the haystack.
    #[test]
    fn every_kernel_agrees_with_the_scalar_one() {
        let restore = vision::active();
        for (w, h) in [(32u32, 24u32), (17, 9), (63, 8), (6, 6)] {
            let tpl = checker_template(w, h);
            let hay = haystack(200, 120, &tpl, 41, 30);
            vision::force_isa(Some(vision::Isa::Scalar));
            let want = vision::find(&hay, &tpl, false)
                .unwrap_or_else(|| panic!("the scalar kernel lost a {w}x{h} template"));
            for (isa, here) in vision::isa_report() {
                if !here {
                    continue;
                }
                vision::force_isa(Some(isa));
                let got = vision::find(&hay, &tpl, false)
                    .unwrap_or_else(|| panic!("{} lost a {w}x{h} template", isa.name()));
                assert_eq!(
                    (got.x, got.y),
                    (want.x, want.y),
                    "{} put a {w}x{h} template somewhere else",
                    isa.name()
                );
                // Float addition is not associative: a wider kernel folds the same
                // numbers in a different order and lands a few ULPs away. The place
                // has to be identical, the score only recognisably the same number.
                assert!(
                    (got.score - want.score).abs() < 1e-3,
                    "{} scored a {w}x{h} template {} against {}",
                    isa.name(),
                    got.score,
                    want.score
                );
            }
        }
        vision::force_isa(Some(restore));
    }

    /// `--simd` takes the kernel names and the `-C target-cpu` spellings that map
    /// onto them, so that the flag someone read about in the README does what they
    /// expect when they type it here.
    #[test]
    fn the_simd_flag_takes_the_target_cpu_names() {
        for (arg, want) in [
            ("scalar", vision::Isa::Scalar),
            ("x86-64", vision::Isa::Sse2),
            ("x86-64-v2", vision::Isa::Sse2),
            ("bdver2", vision::Isa::Avx),
            ("AVX2", vision::Isa::Avx2),
            ("x86-64-v3", vision::Isa::Avx2),
            ("znver3", vision::Isa::Avx2),
            (" znver5 ", vision::Isa::Avx512),
            ("x86-64-v4", vision::Isa::Avx512),
        ] {
            assert_eq!(vision::Isa::parse(arg), Some(want), "--simd {arg}");
        }
        // `auto` is not a kernel - it is the absence of a pin, and main.rs handles
        // it before ever asking here.
        assert_eq!(vision::Isa::parse("auto"), None);
        assert_eq!(vision::Isa::parse("neon"), None);
    }

    /// Whatever the processor turns out to support, the choice has to be one of the
    /// kernels that is actually in the binary and that this machine can run.
    #[test]
    fn the_chosen_kernel_is_one_this_machine_can_run() {
        assert!(vision::active().supported());
        let report = vision::isa_report();
        assert_eq!(report.len(), vision::ISAS.len());
        // The fallback is always available, on any architecture.
        assert!(vision::Isa::Scalar.supported());
        // Widest first, and never wider than what was chosen.
        assert!(report.iter().any(|(i, ok)| *ok && *i == vision::active()));
    }

    /// A wide, short template must be found where it actually is, even when the
    /// coarse pass cannot tell it from a decoy.
    ///
    /// The failure this guards against was silent and therefore the worst kind. The
    /// search sweeps a shrunken copy first and then refines around the winner; a
    /// template much wider than it is tall loses the detail that distinguishes it
    /// when it shrinks, so the coarse pass can prefer somewhere else entirely and
    /// the fine pass never gets to look at the right place. Measured on a real
    /// desktop, a 170x32 button came back 123 px below itself with a score of
    /// 0.867 - above the default threshold of 0.85, so the step reported success and
    /// would have clicked the wrong thing.
    ///
    /// The haystack here is built to force exactly that: two 170x32 patches of fine
    /// vertical stripes, one of period 2 and one of period 3. Shrunk, both average
    /// to the same flat grey and the coarse pass has no way to choose. At full
    /// resolution they are unmistakable. The fix is that the fine pass now gets
    /// several coarse candidates instead of one.
    #[test]
    fn a_wide_short_template_is_not_confused_with_its_decoy() {
        const W: u32 = 600;
        const H: u32 = 240;
        const TW: u32 = 170;
        const TH: u32 = 32;
        let mut px = vec![255u8; (W * H * 4) as usize];
        let put = |px: &mut Vec<u8>, x: u32, y: u32, v: u8| {
            let o = ((y * W + x) * 4) as usize;
            px[o] = v;
            px[o + 1] = v;
            px[o + 2] = v;
            px[o + 3] = 255;
        };
        // A gentle background so the coarse pass has something to hold on to.
        for y in 0..H {
            for x in 0..W {
                put(&mut px, x, y, (120 + (y / 8) % 40) as u8);
            }
        }
        // The real thing, and a decoy that shrinks to the same grey.
        let (rx, ry) = (60u32, 40u32);
        let (dx, dy) = (360u32, 150u32);
        for r in 0..TH {
            for c in 0..TW {
                put(&mut px, rx + c, ry + r, if c % 2 == 0 { 20 } else { 235 });
                put(&mut px, dx + c, dy + r, if c % 3 == 0 { 20 } else { 235 });
            }
        }
        let hay = vision::Frame::rgba(0, 0, W, H, px);

        let mut trgba = Vec::with_capacity((TW * TH * 4) as usize);
        for r in 0..TH {
            let o = (((ry + r) * W + rx) * 4) as usize;
            trgba.extend_from_slice(&hay.px[o..o + (TW * 4) as usize]);
        }
        let tpl = vision::Template { w: TW, h: TH, rgba: trgba, name: "wide".into() };

        let hit = vision::find(&hay, &tpl, false).expect("a wide template must be found");
        assert_eq!(
            (hit.x, hit.y),
            ((rx + TW / 2) as i32, (ry + TH / 2) as i32),
            "found at ({}, {}) with score {:.3} - the decoy is at ({}, {})",
            hit.x,
            hit.y,
            hit.score,
            dx + TW / 2,
            dy + TH / 2
        );
        assert!(hit.score > 0.95, "score was {}", hit.score);
    }

    #[test]
    fn ocr_text_matching_is_forgiving() {
        assert!(ocr::text_matches("You  WIN!", "you win"));
        assert!(ocr::text_matches("Claim reward", "CLAIM"));
        assert!(!ocr::text_matches("Locked", "claim"));
        // An empty needle must never match everything.
        assert!(!ocr::text_matches("anything", ""));
    }

    #[test]
    fn ocr_reads_numbers_from_game_text() {
        assert_eq!(ocr::first_number("Gems: 500"), Some(500.0));
        assert_eq!(ocr::first_number("1,250 coins"), Some(1250.0));
        assert_eq!(ocr::first_number("1 250 coins"), Some(1250.0));
        assert_eq!(ocr::first_number("Energy 42/100"), Some(42.0));
        assert_eq!(ocr::first_number("no digits here"), None);
    }

    #[test]
    fn ocr_reads_a_countdown_as_seconds() {
        assert_eq!(ocr::parse_clock("02:34"), Some(154.0));
        assert_eq!(ocr::parse_clock("Next in 1:02:03"), Some(3723.0));
        assert_eq!(ocr::parse_clock("no clock"), None);
    }

    #[test]
    fn ocr_joins_lines() {
        let boxes = vec![
            ocr::TextBox { text: "one".into(), x: 0, y: 0, w: 1, h: 1, confidence: None },
            ocr::TextBox { text: "two".into(), x: 0, y: 2, w: 1, h: 1, confidence: None },
        ];
        assert_eq!(ocr::joined(&boxes), "one\ntwo");
    }

    #[test]
    fn confidence_averages_only_the_lines_that_gave_one() {
        let line = |c: Option<f32>| ocr::TextBox {
            text: "x".into(),
            x: 0,
            y: 0,
            w: 1,
            h: 1,
            confidence: c,
        };
        // Quarters on purpose: both survive the trip through f32 exactly, so the
        // mean can be compared without a tolerance.
        assert_eq!(ocr::mean_confidence(&[line(Some(0.75)), line(Some(0.25))]), Some(0.5));
        // A line the engine said nothing about is not a line it read badly, and must
        // not drag the average down.
        assert_eq!(ocr::mean_confidence(&[line(Some(0.75)), line(None)]), Some(0.75));
        // Windows OCR never says: no number at all, rather than a zero.
        assert_eq!(ocr::mean_confidence(&[line(None)]), None);
        assert_eq!(ocr::mean_confidence(&[]), None);
    }

    #[test]
    fn finds_a_template_at_the_exact_spot() {
        let tpl = checker_template(32, 24);
        let hay = haystack(320, 240, &tpl, 100, 60);
        let hit = vision::find(&hay, &tpl, false).expect("should find it");
        assert!(hit.score > 0.95, "score was {}", hit.score);
        // The hit reports the centre of the match.
        assert_eq!((hit.x, hit.y), (100 + 16, 60 + 12));
    }

    #[test]
    fn reports_the_frame_origin_in_screen_coordinates() {
        let tpl = checker_template(24, 24);
        let mut hay = haystack(200, 200, &tpl, 40, 30);
        hay.x = 1920; // second monitor
        hay.y = -100;
        let hit = vision::find(&hay, &tpl, false).unwrap();
        assert_eq!((hit.x, hit.y), (1920 + 40 + 12, -100 + 30 + 12));
    }

    #[test]
    fn a_missing_template_scores_low() {
        let tpl = checker_template(32, 32);
        let flat = vision::Frame::rgba(0, 0, 200, 200, vec![90u8; 200 * 200 * 4]);
        let hit = vision::find(&flat, &tpl, false);
        // A featureless screen cannot correlate with a patterned template.
        assert!(hit.map(|h| h.score < 0.5).unwrap_or(true));
    }

    #[test]
    fn template_larger_than_the_screen_is_not_a_match() {
        let tpl = checker_template(64, 64);
        let small = vision::Frame::rgba(0, 0, 32, 32, vec![0u8; 32 * 32 * 4]);
        assert!(vision::find(&small, &tpl, false).is_none());
    }

    #[test]
    fn insert_click_adds_three_events_and_shifts_the_tail() {
        let mut d = MacroData::new(vec![ev(0), ev(100_000)], 100_000);
        editor_insert_click(&mut d, 0, 700, 400);
        assert_eq!(d.events.len(), 5);
        match d.events[2].kind {
            InputEventKind::MouseButton { down: true, x, y, .. } => {
                assert_eq!((x, y), (700, 400))
            }
            _ => panic!("expected a press"),
        }
        // The event that used to follow is pushed back by the click duration.
        assert_eq!(d.events[4].t_us, 130_000);
    }

    fn step(k: StepKind) -> ScriptStep {
        ScriptStep::new(k)
    }

    #[test]
    fn blocks_match_if_else_endif() {
        let steps = vec![
            step(StepKind::If { cond: Condition::Always }),
            step(StepKind::Wait { ms: 1 }),
            step(StepKind::Else),
            step(StepKind::Wait { ms: 2 }),
            step(StepKind::EndIf),
        ];
        let b = resolve_blocks(&steps).unwrap();
        assert_eq!(b.else_of[0], Some(2));
        assert_eq!(b.end_of[0], Some(4));
        assert_eq!(b.end_of[2], Some(4), "Else must know where the block ends");
        assert_eq!(b.start_of[4], Some(0));
    }

    #[test]
    fn blocks_match_nested_while() {
        let steps = vec![
            step(StepKind::While { cond: Condition::Always }),
            step(StepKind::If { cond: Condition::Always }),
            step(StepKind::EndIf),
            step(StepKind::EndWhile),
        ];
        let b = resolve_blocks(&steps).unwrap();
        assert_eq!(b.end_of[0], Some(3));
        assert_eq!(b.end_of[1], Some(2));
        assert_eq!(b.start_of[3], Some(0));
    }

    #[test]
    fn unbalanced_scripts_are_rejected() {
        assert!(resolve_blocks(&[step(StepKind::If { cond: Condition::Always })]).is_err());
        assert!(resolve_blocks(&[step(StepKind::EndIf)]).is_err());
        assert!(resolve_blocks(&[step(StepKind::Else)]).is_err());
        // A While closed by EndIf is a mistake, not a nesting trick.
        assert!(
            resolve_blocks(&[
                step(StepKind::While { cond: Condition::Always }),
                step(StepKind::EndIf),
            ])
            .is_err()
        );
    }

    #[test]
    fn depths_indent_blocks_and_outdent_else() {
        let steps = vec![
            step(StepKind::If { cond: Condition::Always }),
            step(StepKind::Wait { ms: 1 }),
            step(StepKind::Else),
            step(StepKind::Wait { ms: 1 }),
            step(StepKind::EndIf),
        ];
        assert_eq!(script_depths(&steps), vec![0, 1, 0, 1, 0]);
    }

    #[test]
    fn frame_guard_stretches_a_press_that_is_too_short() {
        // 30 FPS -> a 33 ms frame, so a press must survive about 66 ms.
        let mut g = FrameGuard::for_fps(true, 30);
        let down =
            InputEventKind::MouseButton { button: MouseButton::Left, down: true, x: 0, y: 0 };
        let up =
            InputEventKind::MouseButton { button: MouseButton::Left, down: false, x: 0, y: 0 };
        g.note_sent(&down, 1_000_000);
        // Released after 5 ms: the guard has to hold it.
        assert!(g.extra_wait(&up, 1_005_000) >= 50_000);
        // Released after 100 ms: already long enough, nothing added.
        assert_eq!(g.extra_wait(&up, 1_100_000), 0);
    }

    #[test]
    fn frame_guard_separates_a_click_from_the_move_before_it() {
        let mut g = FrameGuard::for_fps(true, 30);
        let mv = InputEventKind::MouseMove { x: 10, y: 10, dx: 0, dy: 0 };
        let down =
            InputEventKind::MouseButton { button: MouseButton::Left, down: true, x: 0, y: 0 };
        g.note_sent(&mv, 2_000_000);
        assert!(g.extra_wait(&down, 2_000_000) >= 30_000);
        assert_eq!(g.extra_wait(&down, 2_100_000), 0);
    }

    /// Every non-letter character allowed to appear anywhere in this file.
    ///
    /// An allowlist, and it has to be one. The first version of the test below
    /// blocked a *range* - Symbols and Pictographs Extended-A, everything from
    /// Unicode 12 - on the theory that egui's bundled font stops there.
    ///
    /// It does not stop anywhere so tidy. Four codepoints from one small block were
    /// tried in 1.6.0 and the coverage turned out to be this:
    ///
    /// ```text
    ///   U+1F9E0  brain          renders   (Scripts, since 1.5.0)
    ///   U+1F9E9  jigsaw piece   empty box
    ///   U+1F9EA  test tube      empty box
    ///   U+1F9F9  broom          empty box
    /// ```
    ///
    /// One glyph in four, with no pattern a range check could express. And the same
    /// block that holds three working icons - U+1F5A5, U+1F5BC, U+1F5D1 - also holds
    /// U+1F5C2, which does not work. There is no rule here, only a list.
    ///
    /// The second version of the test checked the six language tables, which was
    /// still not enough: the mark beside a test run in the run history is built in
    /// `Run::headline` and never goes near them. So the scan is over the whole
    /// source file. Comments are swept up along with the interface text, which costs
    /// nothing and means an em dash in a doc comment is as accounted for as an icon.
    ///
    /// Adding any symbol to this program means adding it here, and that is the
    /// moment to look at it in the running window.
    /// Characters this test has an opinion about: symbols and punctuation, not the
    /// letters of the six languages.
    fn is_symbolish(ch: char) -> bool {
        ch as u32 > 0x2000 && !ch.is_alphabetic() && !ch.is_whitespace()
    }

    /// Every symbol the source draws, including the ones written as `\u{...}`.
    ///
    /// The escapes are the half this test used to miss entirely. A glyph written as
    /// a backslash-u escape is seven ASCII characters in the file, so scanning for
    /// literal characters walked straight past it - which is how a drop-down arrow
    /// and two tick marks shipped as empty boxes for several releases.
    fn symbols_the_source_draws() -> Vec<(usize, char)> {
        let source = include_str!("main.rs");
        let mut out: Vec<(usize, char)> = Vec::new();
        for (n, line) in source.lines().enumerate() {
            for ch in line.chars() {
                if is_symbolish(ch) {
                    out.push((n + 1, ch));
                }
            }
            // Escapes of the backslash-u-brace kind, decoded. Named in words
            // rather than shown, because an example written here is a symbol
            // this very test would then report.
            let bytes = line.as_bytes();
            let mut i = 0;
            while i + 3 < bytes.len() {
                if bytes[i] == b'\\'
                    && bytes[i + 1] == b'u'
                    && bytes[i + 2] == b'{'
                    && let Some(close) = line[i + 3..].find('}')
                {
                    let hex = &line[i + 3..i + 3 + close];
                    if let Ok(cp) = u32::from_str_radix(hex, 16)
                        && let Some(ch) = char::from_u32(cp)
                        && is_symbolish(ch)
                    {
                        out.push((n + 1, ch));
                    }
                    i += 3 + close;
                    continue;
                }
                i += 1;
            }
        }
        out
    }

    /// Does this character actually draw as itself?
    ///
    /// Not `Fonts::has_glyph`, which cannot answer it. That function reports whether
    /// the character resolved to a face other than the one holding the replacement
    /// glyph — so every character genuinely provided *by* that face reports false as
    /// well. Asked about the right-pointing triangle, which renders perfectly, it
    /// says no; asked about a glyph that really is missing, it also says no. Its
    /// own source comment warns of exactly this.
    ///
    /// So this lays the character out and compares where it landed in the font
    /// texture against a codepoint no font has. Two characters that both fall back to
    /// the replacement glyph share one `uv_rect`, because it is one glyph.
    fn draws_as_itself(
        fonts: &mut egui::epaint::text::Fonts,
        id: &egui::FontId,
        c: char,
    ) -> bool {
        let uv = |fonts: &mut egui::epaint::text::Fonts, ch: char| {
            let mut view = fonts.with_pixels_per_point(1.0);
            let g = view.layout_no_wrap(ch.to_string(), id.clone(), egui::Color32::WHITE);
            g.rows
                .first()
                .and_then(|r| r.glyphs.first())
                .map(|glyph| glyph.uv_rect)
        };
        // Characters no font here has, to compare against. They have to be
        // *assigned* characters: a noncharacter such as U+10FFFD is dropped by the
        // shaper rather than drawn as a box, so it produces no glyph at all - and
        // comparing against nothing made every real box look like a real glyph.
        // That is exactly how a drop-down arrow went on shipping as an empty square
        // after this check was supposedly measuring it.
        //
        // Two of them, from different planes, because one font's replacement glyph
        // is not another's.
        let tofu: Vec<_> = [0x13000_u32, 0x10900]
            .into_iter()
            .filter_map(char::from_u32)
            .filter_map(|absent| uv(fonts, absent))
            .collect();
        // No reference box means no measurement. On a machine with no CJK font
        // installed, `font_definitions` adds nothing to the embedded set, the shaper
        // drops both absent codepoints rather than drawing them, and this list comes
        // back empty - at which point the comparison below answers "draws fine" to
        // every character it is ever given, boxes included. That is the same silent
        // pass the comment above describes, arrived at from a different direction,
        // and it is worth a loud failure rather than a green tick that measured
        // nothing. Install a CJK font: the candidate paths are in `font_definitions`.
        assert!(
            !tofu.is_empty(),
            "no font here draws a replacement box, so there is nothing to compare \
             against and this check cannot measure anything. Install a CJK font \
             (Debian/Ubuntu: fonts-noto-cjk, Arch: noto-fonts-cjk)."
        );
        let Some(mine) = uv(fonts, c) else { return false };
        !tofu.contains(&mine)
    }

    /// Nothing in this file may draw a character the fonts cannot draw.
    ///
    /// Measured rather than listed. `ALLOWED_SYMBOLS` was a record of what somebody
    /// had once looked at, so it could not fail on anything nobody had looked at —
    /// which is how two tick marks and a drop-down arrow shipped as empty boxes.
    ///
    /// The CJK ranges are excluded: those come from a Windows font loaded at run
    /// time, so their availability is a property of the machine rather than of this
    /// build, and a gate must not fail because of what is installed.
    #[test]
    fn every_symbol_in_the_source_has_a_glyph_in_the_fonts_we_ship() {
        let mut fonts = egui::epaint::text::Fonts::new(
            egui::epaint::text::TextOptions::default(),
            font_definitions(),
        );
        let prop = egui::FontId::proportional(14.0);
        let mono = egui::FontId::monospace(14.0);
        let from_windows = |c: char| {
            let cp = c as u32;
            (0x3000..=0x303F).contains(&cp) || (0xFF00..=0xFFEF).contains(&cp)
        };

        let mut bad: Vec<(usize, char)> = Vec::new();
        for (line, ch) in symbols_the_source_draws() {
            if from_windows(ch) {
                continue;
            }
            // The proportional family, because that is what nearly all of the
            // interface is drawn in. The two exceptions are listed rather than
            // waved through: each is a symbol that lives only in the monospace
            // font and is only ever used in a monospace label, and each has been
            // looked at on screen.
            let monospace_only = matches!(ch as u32, 0x21B3 | 0x25B8);
            let family = if monospace_only { &mono } else { &prop };
            if !draws_as_itself(&mut fonts, family, ch) {
                bad.push((line, ch));
            }
        }
        bad.sort_by_key(|(_, c)| *c);
        bad.dedup_by_key(|(_, c)| *c);
        assert!(
            bad.is_empty(),
            "these draw as empty boxes:\n{}",
            bad.iter()
                .map(|(l, c)| format!("  line {l}: {c:?} U+{:04X}", *c as u32))
                .collect::<Vec<_>>()
                .join("\n")
        );
    }

    /// The method above has to agree with what is on the screen, or it is just a
    /// different way of being wrong.
    #[test]
    fn the_glyph_check_agrees_with_what_the_window_shows() {
        let mut fonts = egui::epaint::text::Fonts::new(
            egui::epaint::text::TextOptions::default(),
            font_definitions(),
        );
        let prop = egui::FontId::proportional(14.0);
        // Looked at on screen at high magnification: these three draw, and the
        // program has drawn them for several releases.
        for c in ['\u{25b6}', '\u{2714}', '\u{26a0}'] {
            assert!(
                draws_as_itself(&mut fonts, &prop, c),
                "U+{:04X} draws in the window but the check says it does not",
                c as u32
            );
        }
        // And a codepoint nothing has must come back false, or the check passes
        // everything.
        // A drop-down arrow that shipped as an empty square for several releases,
        // and the sentinel itself.
        // Built by arithmetic so the literal escape is not in the file for the
        // scan above to find and then report as a fault of its own.
        for missing in [0x2500_u32 + 0xbe, 0x13000] {
            let c = char::from_u32(missing).unwrap();
            assert!(
                !draws_as_itself(&mut fonts, &prop, c),
                "U+{missing:04X} draws as a box in the window but the check says it is fine"
            );
        }
    }

    /// And nothing may reach for a fullwidth or CJK-punctuation glyph outside
    /// Chinese text, because those depend on a font that may not be installed.
    ///
    /// Chinese text is allowed them: a reader who has set the interface to Chinese
    /// has a font that draws Chinese. It lives in three places rather than one now:
    /// the string table, the handbook's group names, and the handbook's own
    /// articles. The rule that covers all three without listing any of them is that
    /// such a glyph must share its line with an actual ideograph.
    #[test]
    fn only_chinese_text_leans_on_the_windows_font() {
        let source = include_str!("main.rs");
        let lines: Vec<&str> = source.lines().collect();
        for (line, ch) in symbols_the_source_draws() {
            let cp = ch as u32;
            if !((0x3000..=0x303F).contains(&cp) || (0xFF00..=0xFFEF).contains(&cp)) {
                continue;
            }
            let chinese = lines[line - 1]
                .chars()
                .any(|c| ('\u{3400}'..='\u{9fff}').contains(&c));
            assert!(
                chinese,
                "line {line} uses {ch:?} outside Chinese text; it needs a font \
                 that is not shipped with the program"
            );
        }
    }

    #[test]
    fn percentiles_pick_the_worst_samples() {
        // 100 samples: ninety-nine at 10 ms and one 200 ms hitch.
        let mut v = vec![10_000u64; 99];
        v.push(200_000);
        let st = perf::summarize(&v);
        assert_eq!(st.samples, 100);
        assert_eq!(st.worst_us, 200_000);
        // The worst 1 % is the hitch, and it counts as a stutter.
        assert_eq!(st.p99_us, 200_000);
        assert_eq!(st.stutters, 1);
        // A steady window reports no hitches at all.
        assert_eq!(perf::summarize(&[10_000; 50]).stutters, 0);
        assert_eq!(perf::summarize(&[]).samples, 0);
    }

    #[test]
    fn frame_guard_switched_off_never_waits() {
        let mut g = FrameGuard::for_fps(false, 30);
        let down =
            InputEventKind::MouseButton { button: MouseButton::Left, down: true, x: 0, y: 0 };
        let up =
            InputEventKind::MouseButton { button: MouseButton::Left, down: false, x: 0, y: 0 };
        g.note_sent(&down, 0);
        assert_eq!(g.extra_wait(&up, 1), 0);
    }

    #[test]
    fn comparisons_and_var_ops() {
        assert!(Cmp::Lt.test(1.0, 2.0));
        assert!(Cmp::Ge.test(2.0, 2.0));
        assert!(!Cmp::Eq.test(1.0, 2.0));
        assert_eq!(VarOp::Add.apply(3.0, 4.0), 7.0);
        assert_eq!(VarOp::Mul.apply(3.0, 4.0), 12.0);
        assert_eq!(VarOp::Set.apply(3.0, 4.0), 4.0);
    }

    #[test]
    fn step_kind_index_roundtrip() {
        for i in 0..StepKind::COUNT {
            assert_eq!(StepKind::from_index(i).index(), i, "kind {i} does not round-trip");
        }
    }

    #[test]
    fn a_scripted_macro_survives_a_save_and_load() {
        let mut d = MacroData::new(vec![ev(0), ev(1000)], 1000);
        d.script = vec![
            step(StepKind::While { cond: Condition::Var {
                name: "n".into(),
                cmp: Cmp::Lt,
                value: Value::Num(3.0),
            } }),
            step(StepKind::PlayEvents { from: 0, to: 1, between: None }),
            step(StepKind::SetVar {
                name: "n".into(),
                op: VarOp::Add,
                value: Value::Num(1.0),
            }),
            step(StepKind::EndWhile),
        ];
        d.vars.insert("n".into(), Value::Num(0.0));
        let text = serde_json::to_string(&d).unwrap();
        let back = parse_macro(&text).unwrap();
        assert_eq!(back.script.len(), 4);
        assert!(back.has_script());
        assert_eq!(back.vars.get("n"), Some(&Value::Num(0.0)));
    }

    #[test]
    fn a_macro_without_a_script_still_loads() {
        let d = MacroData::new(vec![ev(0), ev(10)], 10);
        let back = parse_macro(&serde_json::to_string(&d).unwrap()).unwrap();
        assert!(!back.has_script());
    }

    #[test]
    fn a_disabled_step_does_not_count_as_a_script() {
        let mut d = MacroData::new(vec![ev(0)], 0);
        d.script = vec![ScriptStep { kind: StepKind::Exit, enabled: false, id: 0 }];
        assert!(!d.has_script());
    }

