    fn coord_map_identity_changes_nothing() {
        assert_eq!(CoordMap::IDENTITY.map(640, 480), (640, 480));
        assert_eq!(CoordMap::IDENTITY.map_delta(-3, 9), (-3, 9));
    }

    #[test]
    fn coord_map_follows_a_moved_window() {
        let m = CoordMap { rx: 100, ry: 100, ox: 400, oy: 250, sx: 1.0, sy: 1.0 };
        assert_eq!(m.map(150, 130), (450, 280));
    }

    #[test]
    fn coord_map_follows_a_resized_window() {
        // Recorded in a 800x600 window at (100,100); now 1600x600 at (0,0).
        let anchor = WindowAnchor { title: "t".into(), x: 100, y: 100, w: 800, h: 600 };
        let m = CoordMap {
            rx: anchor.x,
            ry: anchor.y,
            ox: 0,
            oy: 0,
            sx: 1600.0 / 800.0,
            sy: 1.0,
        };
        // A click halfway across the old window stays halfway across the new one.
        assert_eq!(m.map(500, 400), (800, 300));
        assert_eq!(m.map_delta(10, 10), (20, 10));
    }

    #[test]
    fn bezier_path_starts_and_ends_near_the_line() {
        let mut rng = Rng::new();
        let pts = bezier_path((0, 0), (100, 0), 0.0, &mut rng, 10);
        assert_eq!(pts.len(), 9);
        // With zero curvature the arc collapses onto the straight line.
        assert!(pts.iter().all(|p| p.1.abs() <= 1), "{pts:?}");
        assert!(pts[0].0 < pts[8].0, "points must advance towards the target");
    }

    #[test]
    fn bezier_bows_away_when_curved() {
        // Seeded, and judged over a distribution rather than one draw.
        //
        // Both control-point offsets are random by design, and once in a few hundred
        // draws they both land near zero and the arc really is flat. With
        // `Rng::new`, which seeds itself from the clock and the process id, that made
        // this test fail about one run in four hundred - the worst kind of test,
        // the kind that cries wolf while somebody is looking for a real regression.
        // Found in 1.6.0 while adding the health checks; the curve code itself was
        // never wrong.
        let mut flat = 0;
        for seed in 1..=200u64 {
            let mut rng = seeded(seed);
            let pts = bezier_path((0, 0), (400, 0), 1.0, &mut rng, 16);
            if !pts.iter().any(|p| p.1.abs() > 5) {
                flat += 1;
            }
        }
        // A handful of near-straight draws out of two hundred is the distribution
        // doing its job. A curve setting that did nothing would make all two hundred
        // flat, which is the regression this is here to catch.
        assert!(flat <= 10, "{flat} of 200 curved paths never left the straight line");
    }

