    #[test]
    fn a_flat_recording_with_no_window_to_aim_at_is_flagged() {
        // Coordinates are screen-absolute, and a flat recording is nothing but
        // coordinates. Without a target window or an anchor it is guessing.
        let data = macro_of(20, vec![]);
        let templates = kind_env(&[]);
        let yes = |_: &str| true;
        let none = |_: &str| Vec::new();
        let r = health::check(
            &data,
            &health::Env {
                templates: &templates,
                call_exists: &yes,
                call_targets: &none,
                self_path: None,
                target_window: false,
                ocr_lang: true,
                display: None,
                power_action: false,
            },
        );
        assert!(has(&r, health::Rule::NoTargetWindow));

        // An anchor answers the same question, so it must not be flagged twice.
        let mut anchored = macro_of(20, vec![]);
        anchored.anchor = Some(WindowAnchor {
            title: "Roblox".into(),
            x: 0,
            y: 0,
            w: 800,
            h: 600,
        });
        let r2 = health::check(
            &anchored,
            &health::Env {
                templates: &templates,
                call_exists: &yes,
                call_targets: &none,
                self_path: None,
                target_window: false,
                ocr_lang: true,
                display: None,
                power_action: false,
            },
        );
        assert!(!has(&r2, health::Rule::NoTargetWindow));
    }

    #[test]
    fn a_wait_that_carries_on_when_it_times_out_is_a_warning() {
        let data = macro_of(
            1,
            vec![ScriptStep::new(StepKind::WaitFor {
                cond: Condition::Window { title: "Game".into() },
                appear: true,
                timeout_ms: 5000,
                adaptive: false,
                miss: OnMiss::Continue,
            })],
        );
        assert!(has(&check_with(&data, &kind_env(&[])), health::Rule::WaitCarriesOn));

        // Saying what a timeout means is the fix, so it must clear the warning.
        let data2 = macro_of(
            1,
            vec![ScriptStep::new(StepKind::WaitFor {
                cond: Condition::Window { title: "Game".into() },
                appear: true,
                timeout_ms: 5000,
                adaptive: false,
                miss: OnMiss::Stop,
            })],
        );
        assert!(!has(&check_with(&data2, &kind_env(&[])), health::Rule::WaitCarriesOn));
    }

    #[test]
    fn the_existing_two_checks_are_folded_in_rather_than_duplicated() {
        // Unbalanced blocks and steps after a top-level Quit were already detected
        // in two other places. The editor should have one answer, not three.
        let unbalanced = macro_of(
            1,
            vec![ScriptStep::new(StepKind::If { cond: Condition::Always })],
        );
        assert!(has(&check_with(&unbalanced, &kind_env(&[])), health::Rule::Unbalanced));

        let dead = macro_of(
            1,
            vec![
                ScriptStep::new(StepKind::Exit),
                ScriptStep::new(StepKind::Wait { ms: 1 }),
            ],
        );
        assert!(has(&check_with(&dead, &kind_env(&[])), health::Rule::Unreachable));
    }

    // ---- command palette (1.6.0) --------------------------------------

    #[test]
    fn the_palette_finds_a_command_from_the_middle_of_a_word() {
        // The reason for a subsequence match rather than a substring one.
        assert!(palette::score("Click image", "clik").is_some());
        assert!(palette::score("Click image", "cimg").is_some());
        assert!(palette::score("Click image", "image").is_some());
        // Out of order is not a match: `imgc` is not `Click image` typed badly, it
        // is a different thing.
        assert!(palette::score("Click image", "imgc").is_none());
        assert!(palette::score("Click image", "zzz").is_none());
    }

    #[test]
    fn an_empty_query_matches_everything_so_the_palette_opens_full() {
        let all = ["Wait", "Click image", "Play events"];
        assert_eq!(palette::rank(&all, "", |x| x).len(), 3);
        assert_eq!(palette::rank(&all, "   ", |x| x).len(), 3);
    }

    #[test]
    fn the_shortest_and_earliest_match_ranks_first() {
        // Typing "wait" should offer `Wait` before `Wait for`, and both before
        // something that only happens to contain those letters.
        let all = ["Wait for the window", "Wait", "Set a variable with a tail"];
        let hits = palette::rank(&all, "wait", |x| x);
        assert_eq!(hits[0], &"Wait");
        assert_eq!(hits[1], &"Wait for the window");
    }

    #[test]
    fn matching_ignores_case_in_both_directions() {
        assert!(palette::score("Click image", "CLICK").is_some());
        assert!(palette::score("CLICK IMAGE", "click").is_some());
        // And works in the other five languages this ships in.
        assert!(palette::score("Проверить макрос", "провер").is_some());
        assert!(palette::score("检查宏", "检查").is_some());
    }

    #[test]
    fn every_step_kind_is_reachable_from_the_palette() {
        // The palette exists because the Add menu is about to get much longer. If a
        // step kind were missing from it, the menu would still be the only way.
        let s = get_strings(1, Lang::En);
        for i in 0..StepKind::COUNT {
            let name = StepKind::from_index(i).name(s);
            assert!(
                palette::score(name, name).is_some(),
                "{name} cannot be found by typing its own name"
            );
        }
    }

    // ---- base64 and packaging (1.6.0) ---------------------------------

    #[test]
    fn base64_round_trips_at_every_tail_length() {
        // The three cases are the whole of base64: a group of three bytes, and the
        // two ragged ends. Getting the padding wrong on either end corrupts the last
        // one or two bytes of a PNG, which is exactly the kind of damage that shows
        // up as "the picture search stopped working" rather than as an error.
        for n in 0..40usize {
            let bytes: Vec<u8> = (0..n).map(|i| (i * 7 + 3) as u8).collect();
            let text = b64::encode(&bytes);
            assert_eq!(
                b64::decode(&text).as_deref(),
                Some(&bytes[..]),
                "failed at length {n}: {text}"
            );
        }
    }

    #[test]
    fn base64_matches_the_known_answers() {
        // Against the RFC 4648 vectors, so this is base64 and not merely
        // self-consistent.
        assert_eq!(b64::encode(b""), "");
        assert_eq!(b64::encode(b"f"), "Zg==");
        assert_eq!(b64::encode(b"fo"), "Zm8=");
        assert_eq!(b64::encode(b"foo"), "Zm9v");
        assert_eq!(b64::encode(b"foob"), "Zm9vYg==");
        assert_eq!(b64::encode(b"fooba"), "Zm9vYmE=");
        assert_eq!(b64::encode(b"foobar"), "Zm9vYmFy");
        assert_eq!(b64::decode("Zm9vYmFy").as_deref(), Some(&b"foobar"[..]));
    }

    #[test]
    fn base64_refuses_rubbish_rather_than_inventing_bytes() {
        // A package with a corrupt picture in it should say so, not produce a
        // template made of noise that then fails to match anything for ever.
        assert!(b64::decode("not base64!").is_none());
        assert!(b64::decode("Zg").is_some(), "unpadded but valid");
        assert!(b64::decode("Z").is_none(), "a single character is not a group");
    }

    #[test]
    fn base64_survives_every_byte_value() {
        let all: Vec<u8> = (0..=255u8).collect();
        assert_eq!(b64::decode(&b64::encode(&all)).as_deref(), Some(&all[..]));
    }

    #[test]
    fn a_package_round_trips_through_its_own_format() {
        let mut data = MacroData::new(vec![ev(0), ev(1000)], 1000);
        data.script = vec![ScriptStep::new(StepKind::Wait { ms: 5 })];
        data.normalize().unwrap();

        let mut templates = std::collections::BTreeMap::new();
        templates.insert("claim.png".to_string(), b64::encode(&[1u8, 2, 3, 255]));
        let mut dpi = std::collections::BTreeMap::new();
        dpi.insert("claim.png".to_string(), 144u32);

        let pkg = MacroPackage {
            version: 1,
            main: data,
            macros: Default::default(),
            templates,
            template_dpi: dpi,
            name: "MyAutomation".into(),
            created: "2026-08-26 03:42".into(),
            declared: vec!["mouse".into()],
        };
        let text = serde_json::to_string(&pkg).unwrap();
        let back: MacroPackage = serde_json::from_str(&text).unwrap();
        assert_eq!(back.name, "MyAutomation");
        assert_eq!(back.main.script.len(), 1);
        assert_eq!(
            b64::decode(&back.templates["claim.png"]).unwrap(),
            vec![1u8, 2, 3, 255],
            "the picture survived the trip"
        );
        assert_eq!(back.template_dpi["claim.png"], 144, "and so did its scale");
    }

    #[test]
    fn a_package_missing_every_optional_field_still_loads() {
        // Hand-edited packages are a feature of a format that is meant to be
        // readable, so everything but the macro itself defaults.
        let bare = r#"{"main":{"version":4,"duration_us":1000,
            "events":[{"t_us":0,"kind":{"MouseMove":{"x":1,"y":2,"dx":0,"dy":0}}}]}}"#;
        let pkg: MacroPackage = serde_json::from_str(bare).unwrap();
        assert_eq!(pkg.version, 1);
        assert!(pkg.templates.is_empty());
        assert!(pkg.macros.is_empty());
        assert!(pkg.name.is_empty());
    }

    #[test]
    fn the_dependency_walk_finds_pictures_wherever_they_are_named() {
        // A picture named inside a target's cascade, or as an anchor, is as much a
        // dependency as one named by a plain Click image. Missing one means shipping
        // a package that fails on somebody else's machine.
        let mut data = MacroData::new(vec![ev(0)], 1000);
        data.script = vec![
            ScriptStep::new(StepKind::ClickTarget {
                target: Target {
                    label: "Start".into(),
                    methods: vec![Method::Image {
                        template: "in_a_target".into(),
                        threshold: 0.9,
                        area: SearchArea::NearAnchor {
                            anchor: "an_anchor".into(),
                            dx: 0,
                            dy: 0,
                            w: 10,
                            h: 10,
                        },
                        edge: false,
                    }],
                },
                button: MouseButton::Left,
                invoke: true,
                reliability: Reliability::Maximum,
                timeout_ms: 0,
                miss: OnMiss::Stop,
            }),
            ScriptStep::new(StepKind::WaitFor {
                cond: Condition::Image {
                    template: "in_a_condition".into(),
                    threshold: 0.85,
                    area: SearchArea::FullScreen,
                    lose_at: 0.0,
                    stable_of: 0,
                    stable_in: 0,
                    edge: false,
                },
                appear: true,
                timeout_ms: 100,
                adaptive: false,
                miss: OnMiss::Stop,
            }),
        ];
        let deps = collect_deps(&data, None);
        let names: Vec<&str> = deps.templates.iter().map(|(n, _)| n.as_str()).collect();
        assert!(names.contains(&"in_a_target"), "{names:?}");
        assert!(names.contains(&"in_a_condition"), "{names:?}");
        assert!(names.contains(&"an_anchor"), "an anchor is a dependency too: {names:?}");
    }

    #[test]
    fn a_disabled_step_is_not_a_dependency() {
        // It is not going to run, so its picture does not have to travel.
        let mut step = ScriptStep::new(StepKind::ClickImage {
            template: "unused".into(),
            threshold: 0.9,
            button: MouseButton::Left,
            area: SearchArea::FullScreen,
            edge: false,
            miss: OnMiss::Continue,
        });
        step.enabled = false;
        let mut data = MacroData::new(vec![ev(0)], 1000);
        data.script = vec![step];
        assert!(collect_deps(&data, None).templates.is_empty());
    }

    #[test]
    fn a_call_path_built_from_a_variable_is_not_guessed_at() {
        // It cannot be resolved without running the macro, so it cannot be packed.
        // Reporting it as missing would be a false alarm on every export.
        let mut data = MacroData::new(vec![ev(0)], 1000);
        data.script =
            vec![ScriptStep::new(StepKind::Call { path: "{which}.mrz".into(), miss: OnMiss::Stop })];
        assert!(collect_deps(&data, None).macros.is_empty());
    }

    #[test]
    fn a_dependency_list_knows_whether_it_is_complete() {
        let deps = Deps {
            templates: vec![("a".into(), true), ("b".into(), false)],
            macros: vec![("c".into(), true)],
        };
        assert!(!deps.all_present());
        assert_eq!(deps.missing(), 1);

        let whole = Deps {
            templates: vec![("a".into(), true)],
            macros: vec![],
        };
        assert!(whole.all_present());
        assert_eq!(whole.missing(), 0);
    }

    // ---- block operations (1.6.0) -------------------------------------

    #[test]
    fn a_group_has_no_runtime_meaning_at_all() {
        // The entire design. A group that could change control flow would be a
        // fourth kind of block to reason about, bought for nothing.
        let steps = vec![
            ScriptStep::new(StepKind::Group { name: "Login".into() }),
            ScriptStep::new(StepKind::Wait { ms: 1 }),
            ScriptStep::new(StepKind::EndGroup),
        ];
        let b = resolve_blocks(&steps).expect("a balanced group is valid");
        // It opens nothing and closes nothing.
        assert!(b.end_of.iter().all(|e| e.is_none()));
        assert!(b.start_of.iter().all(|e| e.is_none()));
        assert!(b.else_of.iter().all(|e| e.is_none()));
    }

    #[test]
    fn groups_still_have_to_balance() {
        assert!(resolve_blocks(&[ScriptStep::new(StepKind::Group { name: "x".into() })]).is_err());
        assert!(resolve_blocks(&[ScriptStep::new(StepKind::EndGroup)]).is_err());
        // But they may nest, unlike recovery blocks: a group inside a group is just
        // a heading inside a heading.
        let nested = vec![
            ScriptStep::new(StepKind::Group { name: "a".into() }),
            ScriptStep::new(StepKind::Group { name: "b".into() }),
            ScriptStep::new(StepKind::EndGroup),
            ScriptStep::new(StepKind::EndGroup),
        ];
        assert!(resolve_blocks(&nested).is_ok());
    }

    #[test]
    fn a_group_indents_what_is_inside_it() {
        let steps = vec![
            ScriptStep::new(StepKind::Group { name: "g".into() }),
            ScriptStep::new(StepKind::Wait { ms: 1 }),
            ScriptStep::new(StepKind::EndGroup),
            ScriptStep::new(StepKind::Wait { ms: 2 }),
        ];
        assert_eq!(script_depths(&steps), vec![0, 1, 0, 0]);
    }

    #[test]
    fn wrapping_puts_the_closer_in_before_the_opener() {
        // The order matters: inserting at the front first would shift the index the
        // closer was measured against, and the wrap would enclose one step too few.
        let mut script = vec![
            ScriptStep::new(StepKind::Wait { ms: 1 }),
            ScriptStep::new(StepKind::Wait { ms: 2 }),
            ScriptStep::new(StepKind::Wait { ms: 3 }),
        ];
        wrap_steps(
            &mut script,
            0,
            1,
            StepKind::While { cond: Condition::Always },
            StepKind::EndWhile,
        );
        let kinds: Vec<usize> = script.iter().map(|st| st.kind.index()).collect();
        assert_eq!(
            kinds,
            vec![
                StepKind::While { cond: Condition::Always }.index(),
                1, // Wait
                1, // Wait
                StepKind::EndWhile.index(),
                1, // the third Wait, left outside
            ]
        );
        assert!(resolve_blocks(&script).is_ok());
    }

    #[test]
    fn a_scattered_selection_wraps_everything_between_its_ends() {
        // A linear list cannot express "wrap 3 and 9 but not 4 to 8", and silently
        // doing something else would be worse than doing the obvious thing.
        let marked: std::collections::BTreeSet<usize> = [1usize, 4].into_iter().collect();
        assert_eq!(selection_span(&marked, 0), (1, 4));
        // Nothing marked falls back to the single selected step.
        assert_eq!(selection_span(&Default::default(), 7), (7, 7));
    }

    #[test]
    fn duplicated_steps_get_their_own_identity() {
        // Otherwise the copy would claim the original's statistics.
        let mut data = MacroData::new(vec![ev(0)], 1000);
        data.script = vec![
            ScriptStep::new(StepKind::Wait { ms: 1 }),
            ScriptStep::new(StepKind::Wait { ms: 2 }),
        ];
        data.normalize().unwrap();
        let original = data.script[0].id;
        duplicate_steps(&mut data.script, 0, 0);
        data.normalize().unwrap();
        assert_eq!(data.script.len(), 3);
        assert_eq!(data.script[0].id, original);
        assert_ne!(data.script[1].id, original, "the copy is a new step");
    }

    #[test]
    fn a_run_of_steps_moves_as_a_block() {
        let mk = |ms: u64| ScriptStep::new(StepKind::Wait { ms });
        let mut script = vec![mk(1), mk(2), mk(3), mk(4)];
        // Move steps 1..=2 down one.
        assert!(move_steps(&mut script, 1, 2, true));
        let order: Vec<u64> = script
            .iter()
            .map(|st| match st.kind {
                StepKind::Wait { ms } => ms,
                _ => 0,
            })
            .collect();
        assert_eq!(order, vec![1, 4, 2, 3]);

        // And back up again.
        assert!(move_steps(&mut script, 2, 3, false));
        let order: Vec<u64> = script
            .iter()
            .map(|st| match st.kind {
                StepKind::Wait { ms } => ms,
                _ => 0,
            })
            .collect();
        assert_eq!(order, vec![1, 2, 3, 4]);

        // The ends refuse rather than wrapping around.
        assert!(!move_steps(&mut script, 0, 1, false));
        assert!(!move_steps(&mut script, 2, 3, true));
    }

    // ---- templates (1.6.0) --------------------------------------------

    #[test]
    fn every_template_produces_a_script_that_balances() {
        // A recipe that inserts an unbalanced block would put the macro in a state
        // the checker rejects, which is a bad way to meet a feature.
        for r in templates::ALL.iter() {
            let steps = (r.build)();
            assert!(!steps.is_empty(), "{} builds nothing", (r.name)(&EN));
            assert!(
                resolve_blocks(&steps).is_ok(),
                "{} does not balance: {:?}",
                (r.name)(&EN),
                resolve_blocks(&steps).err()
            );
        }
    }

    #[test]
    fn every_template_has_a_name_in_every_language() {
        for lang in 1..=6usize {
            let s = get_strings(lang, Lang::En);
            for r in templates::ALL.iter() {
                assert!(!(r.name)(s).trim().is_empty(), "a template has no name in {lang}");
            }
        }
    }

    #[test]
    fn a_template_that_names_a_recovery_block_also_provides_one() {
        // The checker reports a policy naming a block nobody wrote. A template that
        // shipped one would be handing the user an error to fix.
        for r in templates::ALL.iter() {
            let steps = (r.build)();
            for st in &steps {
                if let OnMiss::Recover { name } = st.kind.miss() {
                    assert!(
                        recovery_target(&steps, &name).is_some(),
                        "{} names recovery block {name:?} and does not define it",
                        (r.name)(&EN)
                    );
                }
            }
        }
    }

    // ---- optimize recording (1.6.0) -----------------------------------

    fn move_at(t: u64, x: i32, y: i32) -> MacroEvent {
        MacroEvent { t_us: t, kind: InputEventKind::MouseMove { x, y, dx: 0, dy: 0 } }
    }

    #[test]
    fn optimizing_never_removes_anything_visible() {
        // The promise the panel makes. Every press, release and wheel turn survives
        // in order; only the noise between them goes.
        let mut events = vec![
            move_at(0, 10, 10),      // lead-in
            move_at(1_000, 11, 11),  // lead-in, and micro
            move_at(2_000, 400, 400),
        ];
        events.push(click(3_000));
        events.push(move_at(4_000, 401, 401)); // micro
        events.push(move_at(5_000, 402, 401)); // micro
        events.push(click(6_000));
        let before_clicks = events
            .iter()
            .filter(|e| matches!(e.kind, InputEventKind::MouseButton { .. }))
            .count();

        let mut data = MacroData::new(events, 6_000);
        optimize_recording(&mut data);

        let after_clicks = data
            .events
            .iter()
            .filter(|e| matches!(e.kind, InputEventKind::MouseButton { .. }))
            .count();
        assert_eq!(before_clicks, after_clicks, "a click was lost");
        assert!(data.events.len() < 7, "nothing was removed at all");
        // And time still runs forwards.
        assert!(data.events.windows(2).all(|w| w[0].t_us <= w[1].t_us));
    }

    #[test]
    fn the_preview_matches_what_applying_it_does() {
        // The panel shows the plan and a separate button applies it. If the two
        // disagreed, the preview would be a lie.
        let mut events = vec![move_at(0, 5, 5), move_at(1_000, 6, 6), move_at(2_000, 300, 300)];
        events.push(click(3_000));
        events.push(move_at(4_000, 301, 300));
        let mut data = MacroData::new(events, 4_000);

        let plan = plan_cleanup(&data);
        optimize_recording(&mut data);
        assert_eq!(
            plan.after,
            data.events.len(),
            "the preview said {} events and applying it gave {}",
            plan.after,
            data.events.len()
        );
    }

    #[test]
    fn a_long_idle_gap_is_compressed_not_deleted() {
        // The pause is part of the recording — a page was loading. It is capped, not
        // removed, because removing it would replay faster than the thing can react.
        let events = vec![click(0), click(30_000_000)];
        let mut data = MacroData::new(events, 30_000_000);
        optimize_recording(&mut data);
        assert_eq!(data.events.len(), 2, "neither click was removed");
        let gap = data.events[1].t_us - data.events[0].t_us;
        assert_eq!(gap, MAX_IDLE_US, "the gap was capped rather than dropped");
    }

    #[test]
    fn optimizing_a_clean_recording_changes_nothing() {
        let events = vec![click(0), move_at(1_000, 500, 500), click(2_000)];
        let mut data = MacroData::new(events.clone(), 2_000);
        let plan = plan_cleanup(&data);
        assert!(!plan.worth_doing(), "{plan:?}");
        optimize_recording(&mut data);
        assert_eq!(data.events.len(), events.len());
    }

    #[test]
    fn optimizing_brings_the_markers_with_it() {
        // Markers point at event indices, and this renumbers every one of them.
        let mut events = vec![move_at(0, 1, 1), move_at(500, 2, 2)];
        events.push(click(1_000));
        events.push(click(2_000));
        let mut data = MacroData::new(events, 2_000);
        data.markers = vec![Marker { name: "here".into(), at: 3 }];
        optimize_recording(&mut data);
        assert!(
            data.markers[0].at <= data.events.len(),
            "a marker was left pointing past the end"
        );
        assert_eq!(data.markers[0].name, "here");
    }

    // ---- step identity (1.6.0) ----------------------------------------

    #[test]
    fn every_step_gets_an_id_and_an_old_macro_acquires_them_on_load() {
        // Zero means "not assigned", which is what every step in every file written
        // before 1.6.0 has.
        let mut data = MacroData::new(vec![ev(0)], 1000);
        data.script = vec![
            ScriptStep::new(StepKind::Wait { ms: 1 }),
            ScriptStep::new(StepKind::Wait { ms: 2 }),
            ScriptStep::new(StepKind::Wait { ms: 3 }),
        ];
        assert!(data.script.iter().all(|st| st.id == 0));
        data.normalize().unwrap();
        let ids: Vec<u64> = data.script.iter().map(|st| st.id).collect();
        assert_eq!(ids, vec![1, 2, 3]);
    }

    #[test]
    fn a_new_step_never_inherits_a_dead_ones_number() {
        // If it did, the statistics of a deleted step would become the statistics of
        // the step created after it — plausible numbers about the wrong thing.
        let mut data = MacroData::new(vec![ev(0)], 1000);
        data.script = vec![
            ScriptStep::new(StepKind::Wait { ms: 1 }),
            ScriptStep::new(StepKind::Wait { ms: 2 }),
            ScriptStep::new(StepKind::Wait { ms: 3 }),
        ];
        data.normalize().unwrap();
        data.script.remove(1); // id 2 is now dead
        data.script.push(ScriptStep::new(StepKind::Wait { ms: 4 }));
        data.normalize().unwrap();
        let ids: Vec<u64> = data.script.iter().map(|st| st.id).collect();
        assert_eq!(ids, vec![1, 3, 4], "the new step continues past the highest, not into the gap");
    }

    #[test]
    fn two_steps_cannot_share_an_identity() {
        // Copying a step is the obvious way to get two of them, and two steps sharing
        // an id would pool their timings into an average belonging to neither.
        let mut data = MacroData::new(vec![ev(0)], 1000);
        let mut a = ScriptStep::new(StepKind::Wait { ms: 1 });
        a.id = 7;
        let mut b = ScriptStep::new(StepKind::Wait { ms: 2 });
        b.id = 7;
        data.script = vec![a, b];
        data.normalize().unwrap();
        assert_ne!(data.script[0].id, data.script[1].id);
        assert_eq!(data.script[0].id, 7, "the first keeps what it had");
    }

    #[test]
    fn statistics_follow_the_step_when_the_script_is_shuffled() {
        // The whole point of an id. Position is not identity.
        let mut data = MacroData::new(vec![ev(0)], 1000);
        data.script = vec![
            ScriptStep::new(StepKind::Wait { ms: 100 }),
            ScriptStep::new(StepKind::Wait { ms: 200 }),
        ];
        data.normalize().unwrap();
        let (first, second) = (data.script[0].id, data.script[1].id);

        // A run happened, and it was the second step that was slow.
        let mut stats: std::collections::HashMap<u64, StepStats> = Default::default();
        stats.insert(second, StepStats { runs: 10, ok: 10, total_us: 20_000_000, worst_us: 3_000_000 });

        // Now somebody inserts a step at the top and moves things about.
        data.script.insert(0, ScriptStep::new(StepKind::Log { text: "x".into() }));
        data.normalize().unwrap();
        let moved = data.script.iter().find(|st| st.id == second).expect("still there");
        assert!(matches!(moved.kind, StepKind::Wait { ms: 200 }));
        assert_eq!(stats.get(&moved.id).unwrap().runs, 10);
        assert!(!stats.contains_key(&first), "the fast step still has no numbers");
    }

    #[test]
    fn a_suggested_timeout_is_generous_and_never_silly() {
        // Half again the average, floored at the worst ever seen. The floor is the
        // point: an average is what usually happens, and a timeout sized to what
        // usually happens fails on the night it matters.
        let st = StepStats { runs: 50, ok: 50, total_us: 100_000_000, worst_us: 9_220_000 };
        assert_eq!(st.average_us(), 2_000_000);
        assert_eq!(st.suggested_timeout_ms(), 9_220, "the worst case wins over the average");

        let quick = StepStats { runs: 50, ok: 50, total_us: 500_000, worst_us: 12_000 };
        assert_eq!(quick.suggested_timeout_ms(), 200, "never below a fifth of a second");

        // And a handful of runs is an anecdote, not a measurement.
        assert!(!StepStats { runs: 4, ..Default::default() }.trustworthy());
        assert!(StepStats { runs: 5, ..Default::default() }.trustworthy());
    }

    #[test]
    fn success_rate_is_reported_out_of_the_runs_that_happened() {
        let st = StepStats { runs: 312, ok: 305, total_us: 3_432_000, worst_us: 40_000 };
        assert!((st.success() - 97.756).abs() < 0.01, "{}", st.success());
        assert_eq!(StepStats::default().success(), 0.0, "no runs is not a division by zero");
    }

    // ---- recovery blocks (1.6.0) --------------------------------------

    #[test]
    fn a_recovery_block_is_found_by_name_without_case() {
        let steps = vec![
            ScriptStep::new(StepKind::Wait { ms: 1 }),
            ScriptStep::new(StepKind::Recovery { name: "Claim failed".into() }),
            ScriptStep::new(StepKind::EndRecovery),
        ];
        assert_eq!(recovery_target(&steps, "claim failed"), Some(1));
        assert_eq!(recovery_target(&steps, "  CLAIM FAILED  "), Some(1));
        assert_eq!(recovery_target(&steps, "something else"), None);
    }

    #[test]
    fn a_disabled_recovery_block_is_not_found() {
        // A disabled step is a note to self, not a plan — the same rule the checker
        // follows. Jumping into one would run steps the user switched off.
        let mut block = ScriptStep::new(StepKind::Recovery { name: "r".into() });
        block.enabled = false;
        let steps = vec![block, ScriptStep::new(StepKind::EndRecovery)];
        assert_eq!(recovery_target(&steps, "r"), None);
    }

    #[test]
    fn recovery_blocks_have_to_balance() {
        let unclosed = vec![ScriptStep::new(StepKind::Recovery { name: "r".into() })];
        assert!(resolve_blocks(&unclosed).is_err());

        let orphan = vec![ScriptStep::new(StepKind::EndRecovery)];
        assert!(resolve_blocks(&orphan).is_err());

        let nested = vec![
            ScriptStep::new(StepKind::Recovery { name: "a".into() }),
            ScriptStep::new(StepKind::Recovery { name: "b".into() }),
            ScriptStep::new(StepKind::EndRecovery),
            ScriptStep::new(StepKind::EndRecovery),
        ];
        assert!(resolve_blocks(&nested).is_err(), "a block inside a block is not a thing");

        // And one inside an If, which would be a block jumped into from outside the
        // If — not something that can be reasoned about.
        let inside_if = vec![
            ScriptStep::new(StepKind::If { cond: Condition::Always }),
            ScriptStep::new(StepKind::Recovery { name: "r".into() }),
            ScriptStep::new(StepKind::EndRecovery),
            ScriptStep::new(StepKind::EndIf),
        ];
        assert!(resolve_blocks(&inside_if).is_err());

        let ok = vec![
            ScriptStep::new(StepKind::Wait { ms: 1 }),
            ScriptStep::new(StepKind::Recovery { name: "r".into() }),
            ScriptStep::new(StepKind::Wait { ms: 2 }),
            ScriptStep::new(StepKind::EndRecovery),
        ];
        assert!(resolve_blocks(&ok).is_ok());
    }

    #[test]
    fn a_policy_naming_a_block_that_is_not_there_is_an_error() {
        // It looks handled and is not, which is the worst state for a night macro.
        let data = macro_of(
            1,
            vec![ScriptStep::new(StepKind::ClickImage {
                template: "x".into(),
                threshold: 0.9,
                button: MouseButton::Left,
                area: SearchArea::ActiveWindow,
                edge: false,
                miss: OnMiss::Recover { name: "nowhere".into() },
            })],
        );
        let r = check_with(&data, &kind_env(&["x"]));
        assert!(has(&r, health::Rule::RecoveryMissing));
        assert_eq!(r.errors(), 1);

        // With the block present, no complaint.
        let mut ok = data.clone();
        ok.script.push(ScriptStep::new(StepKind::Recovery { name: "nowhere".into() }));
        ok.script.push(ScriptStep::new(StepKind::EndRecovery));
        assert!(!has(&check_with(&ok, &kind_env(&["x"])), health::Rule::RecoveryMissing));
    }

    #[test]
    fn a_recovery_policy_counts_as_a_guard() {
        // It is the strongest guard there is: it does not merely notice the miss, it
        // does something about it.
        let mut data = macro_of(
            1,
            vec![ScriptStep::new(StepKind::ClickImage {
                template: "x".into(),
                threshold: 0.9,
                button: MouseButton::Left,
                area: SearchArea::ActiveWindow,
                edge: false,
                miss: OnMiss::Recover { name: "r".into() },
            })],
        );
        data.script.push(ScriptStep::new(StepKind::Recovery { name: "r".into() }));
        data.script.push(ScriptStep::new(StepKind::EndRecovery));
        let r = check_with(&data, &kind_env(&["x"]));
        assert_eq!(r.aiming.guarded, 1);
        assert_eq!(r.aiming.retries, 1);
    }

    #[test]
    fn a_recovery_policy_survives_the_file() {
        let mut data = MacroData::new(vec![ev(0)], 1000);
        data.script = vec![ScriptStep::new(StepKind::ClickTarget {
            target: Target::default(),
            button: MouseButton::Left,
            invoke: true,
            reliability: Reliability::Maximum,
            timeout_ms: 0,
            miss: OnMiss::Recover { name: "close the popup".into() },
        })];
        let back: MacroData =
            serde_json::from_str(&serde_json::to_string(&data).unwrap()).unwrap();
        assert_eq!(
            back.script[0].kind.miss(),
            OnMiss::Recover { name: "close the popup".into() }
        );
        // And every policy still round-trips through its index.
        for i in 0..OnMiss::COUNT {
            assert_eq!(OnMiss::from_index(i).index(), i);
        }
    }

    // ---- windows (1.6.0) ---------------------------------------------------

    #[test]
    fn a_window_reference_round_trips_and_defaults_to_the_old_behaviour() {
        // `target_title` has always been a title fragment, so that is what a
        // reference with no `by` field has to mean.
        let old = r#"{"value":"Roblox"}"#;
        let w: WindowRef = serde_json::from_str(old).unwrap();
        assert_eq!(w.by, By::Title);
        assert!(w.re_acquire, "looking it up again is the default");

        for i in 0..By::COUNT {
            assert_eq!(By::from_index(i).index(), i);
        }
        for i in 0..WindowAction::COUNT {
            assert_eq!(WindowAction::from_index(i).index(), i);
        }
    }

    #[test]
    fn only_the_window_actions_that_need_fields_ask_for_them() {
        // A row of numbers beside "minimize" is a question nobody asked.
        assert!(WindowAction::Move.uses_xy());
        assert!(WindowAction::Resize.uses_xy());
        assert!(!WindowAction::Minimize.uses_xy());
        assert!(!WindowAction::Activate.uses_xy());

        assert!(WindowAction::WaitActive.waits());
        assert!(WindowAction::WaitAppears.waits());
        assert!(WindowAction::WaitClosed.waits());
        assert!(!WindowAction::Maximize.waits());
    }

    #[test]
    fn closing_a_window_is_the_one_window_action_a_rehearsal_steps_over() {
        // It can lose somebody's work, and no amount of input suppression makes that
        // safe to rehearse. The other ten are harmless.
        let closing = StepKind::Window {
            window: WindowRef::from_title("Notepad"),
            action: WindowAction::Close,
            x: 0,
            y: 0,
            timeout_ms: 0,
            miss: OnMiss::Continue,
        };
        assert!(closing.dangerous());

        let harmless = StepKind::Window {
            window: WindowRef::from_title("Notepad"),
            action: WindowAction::Activate,
            x: 0,
            y: 0,
            timeout_ms: 0,
            miss: OnMiss::Continue,
        };
        assert!(!harmless.dangerous());
    }

    #[test]
    fn a_window_step_reports_the_capability_it_uses() {
        let data = macro_of(
            1,
            vec![ScriptStep::new(StepKind::Window {
                window: WindowRef::from_title("Game"),
                action: WindowAction::Maximize,
                x: 0,
                y: 0,
                timeout_ms: 0,
                miss: OnMiss::Stop,
            })],
        );
        let r = check_with(&data, &kind_env(&[]));
        assert!(r.caps.windows);
        assert!(!r.caps.mouse, "moving a window is not mouse input");
    }

    // ---- clipboard and built-in values (1.6.0) ------------------------

    #[test]
    fn built_in_values_expand_and_a_variable_of_the_same_name_wins() {
        let mut vars: std::collections::HashMap<String, Value> = Default::default();
        // `{screen.width}` is a number this machine can answer for.
        let expanded = expand_vars("w={screen.width}", &vars);
        assert!(expanded.starts_with("w="));
        assert!(
            expanded["w=".len()..].chars().all(|c| c.is_ascii_digit()),
            "{expanded}"
        );

        // Somebody who set `time` meant their `time`.
        vars.insert("time".into(), Value::Str("half past".into()));
        assert_eq!(expand_vars("it is {time}", &vars), "it is half past");
    }

    #[test]
    fn an_unknown_name_is_left_alone_rather_than_deleted() {
        // A typo should be visible, not silently remove part of the text.
        let vars: std::collections::HashMap<String, Value> = Default::default();
        assert_eq!(expand_vars("{clipbaord}", &vars), "{clipbaord}");
        assert_eq!(expand_vars("{{literal}}", &vars), "{literal}");
    }

    #[test]
    fn every_built_in_answers_something() {
        // A name in the palette that expands to nothing would be a menu entry that
        // silently does the wrong thing.
        for name in BUILT_INS {
            assert!(built_in(name).is_some(), "{name} has no value");
        }
        assert!(built_in("not.a.thing").is_none());
    }

    #[test]
    fn only_the_clipboard_actions_that_need_fields_ask_for_them() {
        assert!(ClipAction::Set.uses_text());
        assert!(!ClipAction::Copy.uses_text());
        assert!(ClipAction::Get.uses_var());
        assert!(ClipAction::WaitChange.uses_var());
        assert!(!ClipAction::Clear.uses_var());
        for i in 0..ClipAction::COUNT {
            assert_eq!(ClipAction::from_index(i).index(), i);
        }
    }

