    #[test]
    fn a_display_that_has_changed_is_mentioned_only_where_it_can_matter() {
        let note = RecordingInfo {
            when: "2026-08-27 11:42".into(),
            screen_w: 2560,
            screen_h: 1600,
            dpi: 144,
            ..Default::default()
        };
        let now = RecordingInfo { screen_w: 1920, screen_h: 1080, dpi: 96, ..Default::default() };
        let templates = kind_env(&["claim"]);
        let yes = |_: &str| true;
        let none = |_: &str| Vec::new();
        let run = |data: &MacroData| {
            health::check(
                data,
                &health::Env {
                    templates: &templates,
                    call_exists: &yes,
                    call_targets: &none,
                    self_path: None,
                    target_window: true,
                    ocr_lang: true,
                    display: Some(now.clone()),
                    power_action: false,
                },
            )
        };

        // A flat recording is nothing but coordinates, so both changes matter.
        let mut flat = macro_of(20, vec![]);
        flat.recorded = Some(note.clone());
        let r = run(&flat);
        assert!(has(&r, health::Rule::ScaleChanged));
        assert!(has(&r, health::Rule::ScreenChanged));

        // A macro that aims only by picture does not care: templates carry the scale
        // they were cut at and are matched against the scale of the screen they are
        // being looked for on. Saying otherwise would be telling its author about
        // the weather.
        let mut by_image = macro_of(0, vec![ScriptStep::new(StepKind::ClickImage {
            template: "claim".into(),
            threshold: 0.9,
            button: MouseButton::Left,
            area: SearchArea::NearLast { margin: 160 },
            edge: false,
            miss: OnMiss::Stop,
        })]);
        by_image.recorded = Some(note);
        let r2 = run(&by_image);
        assert!(!has(&r2, health::Rule::ScaleChanged));
        assert!(!has(&r2, health::Rule::ScreenChanged));
    }

    #[test]
    fn the_passed_checks_count_pictures_rather_than_steps_that_want_them() {
        let click = |name: &str| {
            ScriptStep::new(StepKind::ClickImage {
                template: name.into(),
                threshold: 0.9,
                button: MouseButton::Left,
                area: SearchArea::NearLast { margin: 160 },
                edge: false,
                miss: OnMiss::Stop,
            })
        };
        // Three steps, two pictures, one of them missing.
        let data = macro_of(0, vec![click("claim"), click("claim"), click("gone")]);
        let r = check_with(&data, &kind_env(&["claim"]));
        assert_eq!(r.checks.steps, 3);
        assert_eq!(r.checks.templates, 2, "two names, however many steps use them");
        assert_eq!(r.checks.templates_ok, 1);
        assert!(r.checks.balanced && r.checks.reachable && r.checks.no_recursion);
        // The lines the panel and --check both print. A row about nothing is left
        // out - this macro calls nothing, so there is no call row and no recursion
        // row - and the picture row is the one that fails, saying how many of how
        // many rather than a bare total beside a cross.
        let lines = r.checks.lines();
        assert_eq!(lines.len(), 3, "steps, pictures, reachability - and no call rows");
        assert!(lines[0].0 && lines[2].0);
        assert_eq!(lines[1].2, health::Line::Templates);
        assert!(!lines[1].0);
        assert_eq!(lines[1].1, "1 / 2");
    }

