    // ---- 1.8.0: what a run had to do -------------------------------------------

    #[test]
    fn a_run_record_carries_what_it_cost_and_an_older_line_still_loads() {
        let run = runlog::Run {
            started: "2026-08-27 03:42".into(),
            duration_ms: 184_000,
            loops: 42,
            outcome: runlog::Outcome::Finished,
            effort: runlog::Effort {
                fallbacks: 3,
                ocr_retries: 2,
                recoveries: 1,
                recovery_ms: 184,
                missed: 0,
                steps: 42,
            },
            ..Default::default()
        };
        let back: runlog::Run =
            serde_json::from_str(&serde_json::to_string(&run).unwrap()).unwrap();
        assert_eq!(back.effort.fallbacks, 3);
        assert_eq!(back.effort.recovery_ms, 184);
        assert!(!back.effort.quiet());

        // Every run written before 1.8.0 has no `effort` field at all, and has to
        // read as a run that did nothing unusual rather than as a broken line.
        let old = r#"{"started":"2026-08-26 03:42","duration_ms":1,"loops":1,
            "outcome":"Finished","test_run":false}"#;
        let older: runlog::Run = serde_json::from_str(old).unwrap();
        assert!(older.effort.quiet());
        assert_eq!(older.effort.steps, 0);
    }

    #[test]
    fn a_run_that_only_missed_a_step_is_not_a_quiet_one() {
        // The case `Outcome` cannot express: every miss policy says carry on, so the
        // run finishes, and finishing is not the same as having worked.
        let e = runlog::Effort { missed: 1, ..Default::default() };
        assert!(!e.quiet());
        assert!(runlog::Effort::default().quiet());
    }

    // ---- 1.8.0: small things that reach the screen ------------------------------

    #[test]
    fn clipping_text_counts_characters_and_not_bytes() {
        // Everything this is used on can hold text read off a screen, and slicing a
        // string at byte 32 panics the moment that text is Cyrillic.
        let cyrillic = "\u{43f}".repeat(40);
        let cut = clip(&cyrillic, 32);
        assert_eq!(cut.chars().count(), 32);
        assert!(cut.ends_with('\u{2026}'));
        assert_eq!(clip("short", 32), "short");
        assert_eq!(clip("", 4), "");
    }

    #[test]
    fn a_step_duration_reads_in_the_unit_that_suits_it() {
        assert_eq!(format_ms(640), "640 \u{b5}s");
        assert_eq!(format_ms(38_000), "38 ms");
        assert_eq!(format_ms(12_400_000), "12.4 s");
        assert_eq!(bytes(900), "900 B");
        assert_eq!(bytes(4096), "4 KB");
        assert_eq!(bytes(3_145_728), "3.0 MB");
    }

    // ---- run history (1.6.0) ------------------------------------------

    #[test]
    fn a_run_record_round_trips_and_an_older_line_still_loads() {
        let run = runlog::Run {
            started: "2026-08-26 03:42".into(),
            duration_ms: 8_040_000,
            loops: 127,
            outcome: runlog::Outcome::Failed,
            test_run: false,
            effort: runlog::Effort::default(),
            failed_at: Some(17),
            failed_step: "Click image: claim ≥ 0.85".into(),
            reason: "the best match scored 0.41".into(),
            hints: vec!["narrow the search area".into()],
            shot: Some("step17.png".into()),
            folder: "20260826_034200".into(),
            steps: Vec::new(),
            timeline: vec![
                runlog::Mark { at_ms: 0, pc: 0, id: 11 },
                runlog::Mark { at_ms: 41_220, pc: 1, id: 22 },
            ],
            dropped_marks: 3,
        };
        let line = serde_json::to_string(&run).unwrap();
        let back: runlog::Run = serde_json::from_str(&line).unwrap();
        assert_eq!(back.loops, 127);
        assert_eq!(back.outcome, runlog::Outcome::Failed);
        assert_eq!(back.failed_at, Some(17));
        assert_eq!(back.hints.len(), 1);
        assert_eq!(back.timeline.len(), 2);
        assert_eq!(back.timeline[1].at_ms, 41_220);
        assert_eq!(back.dropped_marks, 3);

        // Every field past the first three is `#[serde(default)]`, so a record
        // written by an earlier build - or hand-edited - still loads.
        let sparse = r#"{"started":"2026-01-01 00:00","duration_ms":10,"loops":1}"#;
        let old: runlog::Run = serde_json::from_str(sparse).unwrap();
        assert_eq!(old.outcome, runlog::Outcome::Finished);
        assert!(old.shot.is_none());
        assert!(old.hints.is_empty());
        // Including the two 1.9.5 added: a record from before them is a record with
        // no timeline, not a record that fails to load.
        assert!(old.timeline.is_empty());
        assert_eq!(old.dropped_marks, 0);
    }

    #[test]
    fn a_timeline_keeps_the_end_of_a_long_run_rather_than_its_beginning() {
        // A macro that fails at hour nine is one whose first minute nobody needs. The
        // ring keeps the last marks and counts what fell off, so a timeline can never
        // quietly present itself as the whole run.
        timeline_start();
        for i in 0..(runlog::TIMELINE_MARKS + 50) {
            timeline_mark(i, i as u64);
        }
        let (marks, dropped) = timeline_take();
        assert_eq!(marks.len(), runlog::TIMELINE_MARKS);
        assert_eq!(dropped, 50);
        assert_eq!(marks[0].pc, 50, "the oldest kept mark is the first not dropped");
        assert_eq!(
            marks[marks.len() - 1].pc,
            (runlog::TIMELINE_MARKS + 49) as u32,
            "and the newest is the last one made"
        );

        // Taken means taken: a second run does not inherit the first one's marks.
        let (again, _) = timeline_take();
        assert!(again.is_empty());
    }

    #[test]
    fn a_mark_made_outside_a_run_is_not_recorded() {
        // `timeline_mark` sits on the path every step takes, including the steps of a
        // rehearsal started before anything called `timeline_start`. Without a clock to
        // measure against there is nothing honest to write down.
        let _ = timeline_take();
        timeline_mark(3, 3);
        let (marks, _) = timeline_take();
        assert!(marks.is_empty(), "a mark with no run to belong to");
    }

    #[test]
    fn a_timeline_position_reads_like_a_video_position() {
        // The format exists so that a step at 41 220 ms and a player scrubbed to
        // 00:41.220 are obviously the same moment.
        assert_eq!(format_clock(0), "00:00.000");
        assert_eq!(format_clock(41_220), "00:41.220");
        assert_eq!(format_clock(134_000), "02:14.000");
        assert_eq!(format_clock(3_600_000), "60:00.000");
    }

    #[test]
    fn a_headline_says_at_a_glance_what_happened() {
        let mut run = runlog::Run { started: "2026-08-26 03:42".into(), ..Default::default() };
        assert!(run.headline().starts_with('✔'));
        run.outcome = runlog::Outcome::Failed;
        assert!(run.headline().starts_with('✖'));
        run.outcome = runlog::Outcome::Stopped;
        assert!(run.headline().starts_with('■'));
        // A rehearsal must never be mistaken for evidence that the macro works.
        run.test_run = true;
        assert!(run.headline().contains('✔'));
    }

    #[test]
    fn a_half_written_line_does_not_hide_the_runs_around_it() {
        // A run killed mid-append leaves a truncated line. Losing the other nineteen
        // records over it would be the wrong trade.
        let good = serde_json::to_string(&runlog::Run {
            started: "2026-08-26 01:00".into(),
            loops: 3,
            ..Default::default()
        })
        .unwrap();
        let truncated = r#"{"started":"broken","#;
        let text = format!("{good}
{truncated}
{good}
");
        let parsed: Vec<runlog::Run> = text
            .lines()
            .filter(|l| !l.trim().is_empty())
            .filter_map(|l| serde_json::from_str::<runlog::Run>(l).ok())
            .collect();
        assert_eq!(parsed.len(), 2, "the two intact records survive the broken one");
    }

